/**
 * Treasury Contract Registry
 *
 * Provides registry helpers and RegistryProvider interface for Treasury facets.
 * Uses ATS createRegistryHelpers pattern for consistency.
 *
 * The registry data is auto-generated by `generateRegistryPipeline`.
 * To regenerate: `npm run generate:registry`
 *
 * @module domain/treasuryRegistry
 *
 * @example
 * ```typescript
 * import {
 *     getFacetDefinition,
 *     getAllFacets,
 * } from '@scripts/domain'
 *
 * // Query facets
 * const facet = getFacetDefinition('LifeCycleCashFlowFacet')
 * console.log(facet.methods)
 * console.log(facet.resolverKey)
 *
 * // Get all facets
 * const allFacets = getAllFacets()
 * ```
 */

import { createRegistryHelpers, type RegistryProvider } from "@hashgraph/asset-tokenization-contracts/scripts";
import {
  FACET_REGISTRY,
  INFRASTRUCTURE_CONTRACTS,
  STORAGE_WRAPPER_REGISTRY,
  MOCK_CONTRACTS,
} from "./treasuryRegistry.data";

/**
 * Treasury-specific registry helpers.
 *
 * These helper functions provide type-safe access to our contract registry.
 * Created using the generic factory pattern from ATS infrastructure.
 */
export const {
  getFacetDefinition,
  getContractDefinition,
  getAllFacets,
  getAllContracts,
  hasFacet,
  hasContract,
  FACET_REGISTRY_COUNT,
  getStorageWrapperDefinition,
  getAllStorageWrappers,
  hasStorageWrapper,
  STORAGE_WRAPPER_REGISTRY_COUNT,
} = createRegistryHelpers(FACET_REGISTRY, INFRASTRUCTURE_CONTRACTS, STORAGE_WRAPPER_REGISTRY);

/**
 * Get mock contract definition by name.
 * @param name - Mock contract name
 * @returns Mock contract definition or undefined
 */
export function getMockDefinition(name: string) {
  return MOCK_CONTRACTS[name];
}

/**
 * Get all mock contracts.
 * @returns Array of all mock contracts
 */
export function getAllMocks() {
  return Object.values(MOCK_CONTRACTS);
}

/**
 * Check if mock contract exists in registry.
 * @param name - Mock contract name
 * @returns true if mock exists
 */
export function hasMock(name: string): boolean {
  return name in MOCK_CONTRACTS;
}

/**
 * Treasury registry provider compatible with ATS deployment operations.
 *
 * Provides access to both production facets and mock contracts.
 * Use this when calling ATS functions that expect a RegistryProvider interface.
 *
 * @example
 * ```typescript
 * import { treasuryRegistry } from '@scripts/domain'
 *
 * // Use with ATS deployment operations
 * const facet = treasuryRegistry.getFacetDefinition('LifeCycleCashFlowFacet')
 * ```
 */
export const treasuryRegistry: RegistryProvider = {
  getFacetDefinition(name: string) {
    return getFacetDefinition(name) || getMockDefinition(name);
  },
  getAllFacets() {
    return [...getAllFacets(), ...getAllMocks()];
  },
};
